import AppKit
import SwiftUI

// MARK: - SDKSnippetCodeVariant
//
// Selectable code format in the Studio Capability & Snippet Library.
// `.typescript` is the default primary executable code snippet.

public enum SDKSnippetCodeVariant: String, CaseIterable, Identifiable, Sendable {
    case typescript = "TypeScript"
    case swift = "Swift"
    case manifest = "swiftcode.json"

    public var id: String { rawValue }
}

// MARK: - SDKSnippet
//
// Preset runnable capability snippet surfaced in the Studio Capability & Snippet
// Library. Loaded from `snippets.json` (generated by `npm run build:snippets`
// from `SwiftCode/SDK/TypeScript/package/src/snippets.ts`) and unified with
// the canonical `SDKCapability.all` registry so every capability has an
// executable code snippet.

public struct SDKSnippet: Codable, Identifiable, Hashable, Sendable {
    public let id: String
    public let title: String
    public let description: String
    public let capabilityId: String
    public let tags: [String]
    /// The actual executable TypeScript SDK code snippet (never metadata/description).
    public let code: String

    public init(
        id: String,
        title: String,
        description: String,
        capabilityId: String,
        tags: [String],
        code: String
    ) {
        self.id = id
        self.title = title
        self.description = description
        self.capabilityId = capabilityId
        self.tags = tags
        self.code = code
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case title
        case description
        case capabilityId
        case tags
        case code
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let decodedId = try container.decode(String.self, forKey: .id)
        let decodedTitle = try container.decode(String.self, forKey: .title)
        let decodedDescription = try container.decode(String.self, forKey: .description)
        let decodedCapId = try container.decode(String.self, forKey: .capabilityId)
        let decodedTags = try container.decode([String].self, forKey: .tags)
        let decodedCode = try container.decodeIfPresent(String.self, forKey: .code)

        self.id = decodedId
        self.title = decodedTitle
        self.description = decodedDescription
        self.capabilityId = decodedCapId
        self.tags = decodedTags
        if let c = decodedCode, !c.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            self.code = c
        } else {
            self.code = Self.defaultTypeScriptCode(for: decodedCapId, title: decodedTitle)
        }
    }

    /// Canonical capability metadata from `SDKCapability`, if registered.
    public var capability: SDKCapability? {
        SDKCapability.lookup(capabilityId)
    }

    ///Executable Swift SDK snippet corresponding to this capability.
    public var swiftCode: String {
        Self.defaultSwiftCode(for: capabilityId, title: title)
    }

    /// Ready-to-paste `swiftcode.json` capability declaration entry.
    public var manifestDeclarationJSON: String {
        let escapedReason = description
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
        return """
        {
          "id": "\(capabilityId)",
          "reason": "\(escapedReason)"
        }
        """
    }

    /// Returns the executable code for the requested variant.
    /// Defaults to `.typescript` (the primary executable SDK snippet).
    public func executableCode(for variant: SDKSnippetCodeVariant = .typescript) -> String {
        switch variant {
        case .typescript:
            return code
        case .swift:
            return swiftCode
        case .manifest:
            return manifestDeclarationJSON
        }
    }

    // MARK: - Canonical Code Synthesis for All Capabilities

    public static func defaultTypeScriptCode(for capabilityId: String, title: String) -> String {
        if let entry = ScopesIDLists.byID[capabilityId] {
            switch entry.kind {
            case .view:
                let viewId = entry.viewId ?? capabilityId
                return """
                import type { SwiftCodeContext } from "@swiftcode/sdk";

                export async function runExample(context: SwiftCodeContext): Promise<void> {
                  await context.ui.openView("\(viewId)");
                  context.log.info("\(title) opened", { capabilityId: "\(capabilityId)" });
                }
                """
            case .ipc:
                if capabilityId == "source-control.read" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const status = await context.sourceControl.getStatus();
                      if (!status.isRepository) {
                        context.log.warn("The open project is not a Git repository");
                        return;
                      }
                      const diff = await context.sourceControl.getDiff({ maxBytes: 65536 });
                      context.log.info("Repository status inspected", {
                        branch: status.branchName ?? "(detached HEAD)",
                        changedFiles: diff.files.length,
                      });
                    }
                    """
                } else if capabilityId == "build.execute" {
                    return """
                    import type { SwiftCodeContext, BuildResult } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const handle = await context.build.run({
                        target: "SwiftCode",
                        configuration: "Debug",
                      });
                      for await (const event of handle.output) {
                        context.log.info("[" + event.kind + "] " + event.text);
                      }
                      const result: BuildResult = await handle.wait();
                      context.log.info("Build finished", {
                        status: result.status,
                        errors: result.errorCount,
                        warnings: result.warningCount,
                      });
                    }
                    """
                } else if capabilityId == "use.SwiftCodeModel" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const answer = await context.cloudModel.complete({
                        prompt: "Summarize the current working-tree changes as a one-line commit message.",
                        systemPrompt: "You are a concise technical writer.",
                      });
                      context.log.info("Cloud model answer received", { answer });
                    }
                    """
                } else if capabilityId == "terminal.sandbox" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const result = await context.terminalSandbox.run({
                        command: "git",
                        args: ["status", "--short"],
                        timeout: 30,
                      });
                      context.log.info("Sandboxed command finished", {
                        exitCode: result.exitCode,
                        stdout: result.stdout.trim(),
                      });
                    }
                    """
                } else if capabilityId.hasPrefix("use.Security") || capabilityId == "credentials.use" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const added = await context.security.addValue("api-keys", "service-token", {
                        label: "Service API Token",
                        prompt: "Enter the API token to store in the macOS Keychain.",
                      });
                      const exists = await context.security.hasValue("api-keys", added.valueID);
                      context.log.info("Keychain secret verified", {
                        valueID: added.valueID,
                        exists,
                      });
                    }
                    """
                } else if capabilityId == "ui.contribute" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      context.commands.register({
                        id: "run-custom-action",
                        title: "\(title)",
                        execute: async () => {
                          context.log.info("Executed contributed command");
                          return { ok: true };
                        },
                      });
                    }
                    """
                } else if capabilityId == "project.read" || capabilityId == "workspace.read" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const project = await context.project.getCurrent();
                      if (!project) {
                        context.log.warn("No project is currently open");
                        return;
                      }
                      context.log.info("Project metadata loaded", {
                        id: project.id,
                        name: project.name,
                        rootPath: project.rootPath,
                      });
                    }
                    """
                } else if capabilityId == "assist.invoke" {
                    return """
                    import type { SwiftCodeContext } from "@swiftcode/sdk";

                    export async function runExample(context: SwiftCodeContext): Promise<void> {
                      const session = await context.assist.createSession({
                        systemPrompt: "You are a concise Swift engineering assistant.",
                      });
                      try {
                        const reply = await context.assist.sendMessage(
                          session.sessionId,
                          "Summarize the active project structure."
                        );
                        context.log.info("Assist reply", { reply });
                      } finally {
                        await context.assist.closeSession(session.sessionId);
                      }
                    }
                    """
                }
            case .entitlement:
                break
            }
        }

        return """
        import type { SwiftCodeContext } from "@swiftcode/sdk";

        export async function runExample(context: SwiftCodeContext): Promise<void> {
          const project = await context.project.getCurrent();
          context.log.info("Executed \(title)", {
            capability: "\(capabilityId)",
            project: project?.name ?? "none",
          });
        }
        """
    }

    public static func defaultSwiftCode(for capabilityId: String, title: String) -> String {
        return """
        import Foundation
        import SwiftCodeSDK

        public func runCapabilityExample(client: SDKClient) async throws {
            let granted = await client.permissions.hasCapability("\(capabilityId)")
            guard granted else {
                throw SDKClientError.capabilityDenied("\(capabilityId)")
            }
            let workspace = try await client.workspace.currentProject()
            print("[\(capabilityId)] Active project: \\(workspace.name) at \\(workspace.rootPath)")
        }
        """
    }
}

// MARK: - SDKSnippetCategoryFilter

public enum SDKSnippetCategoryFilter: String, CaseIterable, Identifiable, Sendable {
    case all = "All"
    case project = "Project"
    case sourceControl = "Source Control"
    case build = "Build & Tasks"
    case ui = "UI & Views"
    case security = "Security"
    case ai = "AI & Cloud"

    public var id: String { rawValue }

    public func matches(_ snippet: SDKSnippet) -> Bool {
        switch self {
        case .all:
            return true
        case .project:
            return snippet.capabilityId.hasPrefix("project.") || snippet.capabilityId.hasPrefix("workspace.")
        case .sourceControl:
            return snippet.capabilityId.hasPrefix("source-control.")
        case .build:
            return snippet.capabilityId.hasPrefix("build.") ||
                   snippet.capabilityId.hasPrefix("task.") ||
                   snippet.capabilityId == "terminal.sandbox" ||
                   snippet.capabilityId == "ci.VisualWF"
        case .ui:
            if let entry = ScopesIDLists.byID[snippet.capabilityId], entry.kind == .view {
                return true
            }
            return snippet.capabilityId == "ui.contribute"
        case .security:
            return snippet.capabilityId.hasPrefix("use.Security") ||
                   snippet.capabilityId == "credentials.use" ||
                   snippet.capabilityId == "network.request"
        case .ai:
            return snippet.capabilityId == "use.SwiftCodeModel" ||
                   snippet.capabilityId == "assist.invoke"
        }
    }
}

// MARK: - SDKSnippetStore
//
// Loads snippets from `snippets.json` (in Bundle.main or the repository /
// installed SDK paths) and ensures every capability in `SDKCapability.all`
// is represented with a real executable code snippet.

public enum SDKSnippetStore {

    /// Loads the complete snippet catalog, unifying `snippets.json` with
    /// `SDKCapability.all` so every canonical capability has runnable code.
    public static func loadAll() -> [SDKSnippet] {
        var loadedSnippets: [SDKSnippet] = []

        for url in candidateSnippetJSONURLs() {
            if let data = try? Data(contentsOf: url),
               let decoded = try? JSONDecoder().decode([SDKSnippet].self, from: data),
               !decoded.isEmpty {
                loadedSnippets = decoded
                break
            }
        }

        var seenCapabilityIDs = Set(loadedSnippets.map(\.capabilityId))
        var seenSnippetIDs = Set(loadedSnippets.map(\.id))

        // Ensure every canonical capability in `SDKCapability.all` is present.
        for cap in SDKCapability.all where !seenCapabilityIDs.contains(cap.id) {
            let syntheticID = cap.id
                .lowercased()
                .replacingOccurrences(of: ".", with: "-")
            let uniqueID = seenSnippetIDs.contains(syntheticID) ? "cap-\(syntheticID)" : syntheticID
            seenSnippetIDs.insert(uniqueID)
            seenCapabilityIDs.insert(cap.id)

            let tags = cap.id.split(separator: ".").map(String.init) + [cap.category.rawValue]
            let code = SDKSnippet.defaultTypeScriptCode(for: cap.id, title: cap.title)
            loadedSnippets.append(
                SDKSnippet(
                    id: uniqueID,
                    title: cap.title,
                    description: cap.summary,
                    capabilityId: cap.id,
                    tags: tags,
                    code: code
                )
            )
        }

        return loadedSnippets
    }

    /// Filters `snippets` by category and case-insensitive search query across
    /// `id`, `title`, `description`, `capabilityId`, `tags`, and `code`.
    public static func filter(
        _ snippets: [SDKSnippet],
        query: String,
        category: SDKSnippetCategoryFilter = .all
    ) -> [SDKSnippet] {
        let categoryFiltered = snippets.filter { category.matches($0) }
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !trimmed.isEmpty else { return categoryFiltered }
        return categoryFiltered.filter { snippet in
            if snippet.id.lowercased().contains(trimmed) { return true }
            if snippet.title.lowercased().contains(trimmed) { return true }
            if snippet.description.lowercased().contains(trimmed) { return true }
            if snippet.capabilityId.lowercased().contains(trimmed) { return true }
            if snippet.tags.contains(where: { $0.lowercased().contains(trimmed) }) { return true }
            if snippet.code.lowercased().contains(trimmed) { return true }
            return false
        }
    }

    /// Copies the executable code snippet for `snippet` (in the requested `variant`)
    /// to `NSPasteboard.general` and returns the exact string placed on the pasteboard.
    /// NEVER copies the description or metadata summary.
    @discardableResult
    public static func copyCode(
        of snippet: SDKSnippet,
        variant: SDKSnippetCodeVariant = .typescript
    ) -> String {
        let codeToCopy = snippet.executableCode(for: variant)
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(codeToCopy, forType: .string)
        return codeToCopy
    }

    private static func candidateSnippetJSONURLs() -> [URL] {
        var urls: [URL] = []
        if let bundled = Bundle.main.url(forResource: "snippets", withExtension: "json") {
            urls.append(bundled)
        }
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
        if let appSupport {
            urls.append(
                appSupport
                    .appendingPathComponent("SwiftCode/SDK/TypeScript/package/snippets.json")
            )
        }
        // Source tree fallback for local development and tests
        let sourceFallback = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // Views
            .deletingLastPathComponent() // CodeEditor
            .deletingLastPathComponent() // Studio
            .appendingPathComponent("TypeScript/package/snippets.json")
        urls.append(sourceFallback)
        return urls
    }
}

// MARK: - SDKCodeSnippetLibraryView

public struct SDKCodeSnippetLibraryView: View {

    @ObservedObject private var editorState: SDKCodeEditorState
    private var onInsertIntoManifest: ((String, String) -> Void)?

    @State private var allSnippets: [SDKSnippet] = []
    @State private var searchQuery: String = ""
    @State private var selectedCategory: SDKSnippetCategoryFilter = .all
    @State private var selectedVariant: SDKSnippetCodeVariant = .typescript
    @State private var expandedSnippetIDs: Set<String> = []
    @State private var copiedSnippetID: String?
    @State private var insertedSnippetID: String?

    public init(
        editorState: SDKCodeEditorState? = nil,
        onInsertIntoManifest: ((String, String) -> Void)? = nil
    ) {
        self._editorState = ObservedObject(wrappedValue: editorState ?? SDKCodeEditorState())
        self.onInsertIntoManifest = onInsertIntoManifest
    }

    private var visibleSnippets: [SDKSnippet] {
        SDKSnippetStore.filter(allSnippets, query: searchQuery, category: selectedCategory)
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            headerBar
            Divider()
            categoryFilterBar
            Divider()
            searchBar
            Divider()
            contentArea
        }
        .frame(minWidth: 280, idealWidth: 340, maxWidth: .infinity, maxHeight: .infinity)
        .background(Color(nsColor: .controlBackgroundColor))
        .onAppear {
            if allSnippets.isEmpty {
                allSnippets = SDKSnippetStore.loadAll()
                if let first = allSnippets.first {
                    expandedSnippetIDs.insert(first.id)
                }
            }
        }
    }

    // MARK: - Header & Variant Bar

    private var headerBar: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 6) {
                Image(systemName: "curlybraces.square.fill")
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundStyle(Color.accentColor)
                Text("SDK Capability & Snippet Library")
                    .font(.system(size: 12, weight: .semibold))
                Spacer()
                Text("\(visibleSnippets.count) / \(allSnippets.count)")
                    .font(.system(size: 10, weight: .medium, design: .monospaced))
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(
                        Capsule()
                            .fill(Color.primary.opacity(0.06))
                    )
            }

            HStack(spacing: 6) {
                Text("Code Format:")
                    .font(.system(size: 10, weight: .medium))
                    .foregroundStyle(.secondary)
                Picker("", selection: $selectedVariant) {
                    ForEach(SDKSnippetCodeVariant.allCases) { variant in
                        Text(variant.rawValue).tag(variant)
                    }
                }
                .pickerStyle(.segmented)
                .controlSize(.small)
                .labelsHidden()
            }
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 8)
    }

    // MARK: - Category Filter Bar

    private var categoryFilterBar: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 5) {
                ForEach(SDKSnippetCategoryFilter.allCases) { category in
                    let isSelected = selectedCategory == category
                    Button {
                        selectedCategory = category
                    } label: {
                        Text(category.rawValue)
                            .font(.system(size: 10, weight: isSelected ? .semibold : .regular))
                            .foregroundStyle(isSelected ? Color.white : Color.primary)
                            .padding(.horizontal, 8)
                            .padding(.vertical, 4)
                            .background(
                                Capsule()
                                    .fill(isSelected ? Color.accentColor : Color.primary.opacity(0.07))
                            )
                    }
                    .buttonStyle(.plain)
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
        }
    }

    // MARK: - Search bar

    private var searchBar: some View {
        HStack(spacing: 6) {
            Image(systemName: "magnifyingglass")
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
            TextField("Filter by capability ID, title, tag, or code…", text: $searchQuery)
                .textFieldStyle(.plain)
                .font(.system(size: 12))
            if !searchQuery.isEmpty {
                Button {
                    searchQuery = ""
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 11))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .help("Clear filter")
            }
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
    }

    // MARK: - Content

    @ViewBuilder
    private var contentArea: some View {
        if allSnippets.isEmpty {
            emptyState(
                icon: "exclamationmark.triangle",
                title: "No capabilities loaded",
                detail: "The SDK capability catalog could not be initialized."
            )
        } else if visibleSnippets.isEmpty {
            emptyState(
                icon: "magnifyingglass",
                title: "No matching capabilities",
                detail: "No snippet matched \"\(searchQuery)\" in \(selectedCategory.rawValue)."
            )
        } else {
            ScrollView {
                LazyVStack(alignment: .leading, spacing: 10) {
                    ForEach(visibleSnippets) { snippet in
                        snippetCard(snippet)
                    }
                }
                .padding(10)
            }
        }
    }

    private func emptyState(icon: String, title: String, detail: String) -> some View {
        VStack(spacing: 6) {
            Image(systemName: icon)
                .font(.system(size: 20))
                .foregroundStyle(.tertiary)
            Text(title)
                .font(.system(size: 12, weight: .medium))
                .foregroundStyle(.secondary)
            Text(detail)
                .font(.system(size: 11))
                .foregroundStyle(.tertiary)
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding(16)
    }

    // MARK: - Snippet card

    private func snippetCard(_ snippet: SDKSnippet) -> some View {
        let isCopied = copiedSnippetID == snippet.id
        let isInserted = insertedSnippetID == snippet.id
        let isExpanded = expandedSnippetIDs.contains(snippet.id)
        let activeCode = snippet.executableCode(for: selectedVariant)

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 6) {
                Button {
                    if isExpanded {
                        expandedSnippetIDs.remove(snippet.id)
                    } else {
                        expandedSnippetIDs.insert(snippet.id)
                    }
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: isExpanded ? "chevron.down" : "chevron.right")
                            .font(.system(size: 9, weight: .bold))
                            .foregroundStyle(.secondary)
                            .frame(width: 10)
                        Text(snippet.title)
                            .font(.system(size: 12, weight: .semibold))
                            .foregroundStyle(.primary)
                            .multilineTextAlignment(.leading)
                    }
                }
                .buttonStyle(.plain)

                Spacer(minLength: 4)

                // Insert into Editor button
                Button {
                    insertSnippetCode(snippet)
                } label: {
                    HStack(spacing: 3) {
                        Image(systemName: isInserted ? "checkmark" : "arrow.down.doc")
                            .font(.system(size: 10, weight: .medium))
                        Text(isInserted ? "Inserted" : "Insert")
                            .font(.system(size: 10, weight: .medium))
                    }
                    .padding(.horizontal, 6)
                    .padding(.vertical, 3)
                    .background(
                        RoundedRectangle(cornerRadius: 4)
                            .fill(Color.primary.opacity(0.08))
                    )
                }
                .buttonStyle(.plain)
                .help("Insert executable \(selectedVariant.rawValue) snippet into the active editor")

                // Copy executable code button
                Button {
                    copyExecutableCode(of: snippet)
                } label: {
                    HStack(spacing: 3) {
                        Image(systemName: isCopied ? "checkmark" : "doc.on.doc")
                            .font(.system(size: 10, weight: .medium))
                        Text(isCopied ? "Copied" : "Copy")
                            .font(.system(size: 10, weight: .medium))
                    }
                    .foregroundStyle(isCopied ? Color.white : Color.accentColor)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 3)
                    .background(
                        RoundedRectangle(cornerRadius: 4)
                            .fill(isCopied ? Color.green : Color.accentColor.opacity(0.14))
                    )
                }
                .buttonStyle(.plain)
                .help("Copy executable \(selectedVariant.rawValue) code snippet to clipboard")
            }

            // Capability ID + risk badge row
            HStack(spacing: 6) {
                HStack(spacing: 4) {
                    Image(systemName: "key.fill")
                        .font(.system(size: 9))
                        .foregroundStyle(Color.accentColor)
                    Text(snippet.capabilityId)
                        .font(.system(size: 10, weight: .semibold, design: .monospaced))
                        .foregroundStyle(Color.accentColor)
                }
                .padding(.horizontal, 6)
                .padding(.vertical, 2)
                .background(
                    RoundedRectangle(cornerRadius: 4)
                        .fill(Color.accentColor.opacity(0.12))
                )

                if let cap = snippet.capability {
                    riskBadge(for: cap.riskLevel)
                }

                Spacer()

                if let onInsertIntoManifest {
                    Button {
                        onInsertIntoManifest(snippet.capabilityId, snippet.description)
                    } label: {
                        HStack(spacing: 3) {
                            Image(systemName: "plus.circle")
                                .font(.system(size: 9))
                            Text("Add to Manifest")
                                .font(.system(size: 9, weight: .medium))
                        }
                        .foregroundStyle(.secondary)
                    }
                    .buttonStyle(.plain)
                    .help("Add \(snippet.capabilityId) to swiftcode.json capabilities")
                }
            }

            Text(snippet.description)
                .font(.system(size: 11))
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)

            if isExpanded {
                VStack(alignment: .leading, spacing: 4) {
                    HStack {
                        Text("\(selectedVariant.rawValue) Snippet")
                            .font(.system(size: 9, weight: .semibold))
                            .foregroundStyle(.secondary)
                        Spacer()
                        Button {
                            copyExecutableCode(of: snippet)
                        } label: {
                            Text("Copy \(selectedVariant.rawValue)")
                                .font(.system(size: 9, weight: .medium))
                                .foregroundStyle(Color.accentColor)
                        }
                        .buttonStyle(.plain)
                    }

                    ScrollView(.horizontal, showsIndicators: true) {
                        Text(activeCode.trimmingCharacters(in: .whitespacesAndNewlines))
                            .font(.system(size: 10.5, design: .monospaced))
                            .foregroundStyle(.primary)
                            .textSelection(.enabled)
                            .padding(8)
                            .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    .background(
                        RoundedRectangle(cornerRadius: 5)
                            .fill(Color(nsColor: .textBackgroundColor))
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: 5)
                            .stroke(Color.primary.opacity(0.1), lineWidth: 1)
                    )
                }
            }

            if !snippet.tags.isEmpty {
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 4) {
                        ForEach(snippet.tags, id: \.self) { tag in
                            Text("#\(tag)")
                                .font(.system(size: 9.5, design: .monospaced))
                                .foregroundStyle(.secondary)
                                .padding(.horizontal, 5)
                                .padding(.vertical, 1.5)
                                .background(
                                    RoundedRectangle(cornerRadius: 3)
                                        .fill(Color.secondary.opacity(0.10))
                                )
                        }
                    }
                }
            }
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 7)
                .fill(Color(nsColor: .textBackgroundColor).opacity(0.65))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 7)
                .stroke(Color.primary.opacity(0.08), lineWidth: 1)
        )
    }

    private func riskBadge(for risk: SDKCapabilityRisk) -> some View {
        let color: Color = {
            switch risk {
            case .low: return .green
            case .medium: return .blue
            case .high: return .orange
            case .critical: return .red
            }
        }()
        return Text(risk.rawValue.uppercased())
            .font(.system(size: 8.5, weight: .bold, design: .monospaced))
            .foregroundStyle(color)
            .padding(.horizontal, 5)
            .padding(.vertical, 1.5)
            .background(
                RoundedRectangle(cornerRadius: 3)
                    .fill(color.opacity(0.14))
            )
    }

    // MARK: - Copy & Insert Actions

    private func copyExecutableCode(of snippet: SDKSnippet) {
        SDKSnippetStore.copyCode(of: snippet, variant: selectedVariant)
        copiedSnippetID = snippet.id
        let copiedID = snippet.id
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            if copiedSnippetID == copiedID {
                copiedSnippetID = nil
            }
        }
    }

    private func insertSnippetCode(_ snippet: SDKSnippet) {
        let codeToInsert = snippet.executableCode(for: selectedVariant)
        editorState.insertCodeSnippet(
            codeToInsert,
            preferredLanguage: selectedVariant == .swift ? .swift : (selectedVariant == .manifest ? .json : .typescript),
            suggestedTitle: "\(snippet.id).\(selectedVariant == .swift ? "swift" : (selectedVariant == .manifest ? "json" : "ts"))"
        )
        insertedSnippetID = snippet.id
        let targetID = snippet.id
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            if insertedSnippetID == targetID {
                insertedSnippetID = nil
            }
        }
    }
}
